export function createFacebookStage({icon,onDemo}){
 const root=document.createElement('div');root.className='facebook-stage';
 root.innerHTML=`<section class="facebook-intro"><div class="facebook-mark" aria-label="Meta"></div><h1>开始使用<br>Meta 业务工具</h1><p>在独立环境中管理你的 Facebook Business 账号。</p><div class="facebook-features"><div><span>01</span><p>按业务分组，保存各账号的本地备注</p></div><div><span>02</span><p>为每个账号分别配置代理与翻译</p></div><div><span>03</span><p>切换账号时保留各自的环境配置</p></div></div><small>Facebook Business · 独立账号环境</small></section><section class="facebook-login"><div class="facebook-login-content"><div class="facebook-login-mark"></div><h2>登录 Meta 业务工具</h2><div class="facebook-login-placeholder"><span class="facebook-lock"></span><strong>官方登录区域</strong><p>正式桌面版将在此加载 Meta 官方登录页面。</p></div><div class="facebook-login-note"><span>界面演示</span><p>尚未连接 Facebook Business。此处不收集账号或密码。</p></div><button type="button" class="button facebook-demo-button">体验翻译对话</button><small>可在右侧“翻译”中设置当前账号的翻译语言</small></div><div class="facebook-footer-brand">Meta · Business</div></section>`;
 root.querySelector('.facebook-mark').innerHTML=icon('meta',80);root.querySelector('.facebook-login-mark').innerHTML=icon('meta',40);root.querySelector('.facebook-lock').innerHTML=icon('lock',24);root.querySelector('button').onclick=onDemo;return root;
}
